using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using SplifyWin;
class CopyTurnProfile20261023 {
 static int Main(string[] args){try{string source=Path.GetFullPath(args[0]),dest=Path.GetFullPath(args[1]);if(Directory.Exists(dest))throw new Exception("Fresh isolated profile required");Directory.CreateDirectory(dest);foreach(var name in new[]{"client.json","vk-turn.dat"}){var file=Path.Combine(source,name);if(File.Exists(file))File.Copy(file,Path.Combine(dest,name));}var s=new StateStore(dest).Load();var node=s.Servers.FirstOrDefault(n=>n.Id==s.SelectedServerId);Console.WriteLine(new JavaScriptSerializer().Serialize(new{Mode=s.Mode,DnsProvider=s.DnsProvider,DnsProtocol=s.DnsProtocol,AutoSelect=s.AutoSelect,Selected=node==null?null:new{Protocol=node.Protocol,Generation=node.Protocol=="csqtt"?CsqttGenerations.For(node).Id:"",HasNodeOptions=node.TurnPreferences!=null},Servers=s.Servers.Select(n=>new{Protocol=n.Protocol,Generation=n.Protocol=="csqtt"?CsqttGenerations.For(n).Id:"",Selected=n.Id==s.SelectedServerId}).ToArray(),Rules=s.Lists.Select(l=>new{Target=l.Target,ExcludeRussia=l.ExcludeRussia,Entries=(l.Text??"").Split('\n').Length}).ToArray(),ExcludedApplications=s.ExcludedApplications}));if(node==null||node.Protocol!="csqtt"||CsqttGenerations.For(node).Id!="2.5")return 2;SecretStorage.Write(Path.Combine(dest,"live-input.dat"),node.Link);Console.WriteLine("ISOLATED current selected CSQTT2.5 prepared; source unchanged");return 0;}catch(Exception ex){Console.WriteLine("COPY failed "+ex.GetType().Name);return 1;}}
}
